insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('palmistry', 'Palmistry', 'Photograph both palms and receive a personalised, AI-generated reading. Entertainment and self-reflection only.', 'Palmistry works differently from a standard questionnaire: you photograph both palms with an on-screen hand-position guide, answer a few contextual questions, and receive a personalised AI-generated reading covering your heart line, head line, life line, fate line, hand shape, finger proportions, palm mounts, and other visible markers. This is offered purely for entertainment and self-reflection — it carries no scientific validity claim, is not a psychological or medical assessment, and never contributes to your EvalOtter cognitive score.', 'hand', (select id from assessment_categories where key = 'self-discovery'), ('vision_analysis')::assessment_engine_type, ('easy')::assessment_difficulty, 5, 4, false, ('free')::assessment_access, ('published')::assessment_status)
