insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values ((select current_version_id from assessments where slug = 'palmistry'), 'About You', 'A few questions to personalise your reading.', 'These help tailor the AI-generated reading to you — there are no right or wrong answers.', NULL, false, 1, 1);
