  ((select current_version_id from assessments where slug = 'palmistry'), (select id from assessment_sections where assessment_version_id = (select current_version_id from assessments where slug = 'palmistry') and name = 'About You'), (select id from questions where external_key = 'palmistry-02'), 1, 1),
